                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

import { useState, useRef, useEffect } from "react";
import { useMapsLibrary } from "@vis.gl/react-google-maps";
import { Dialog, DialogContent } from "./ui/dialog";
import { Clock, Search, MapPin, X, Loader2, Target } from "lucide-react";
import { useSettings } from "../contexts/SettingsContext";
import { translations } from "../lib/translations";
import { useDebounce } from "../hooks/useDebounce";

export function LocationSearchModal({ 
  isOpen, 
  onClose, 
  item,
  onSelectLocation
}: {
  isOpen: boolean;
  onClose: () => void;
  item: any;
  onSelectLocation: (id: string, address: string, coords: { lat: number, lng: number }) => void;
}) {
  const { language } = useSettings();
  const t = translations[language];

  const [searchValue, setSearchValue] = useState("");
  const debouncedSearchValue = useDebounce(searchValue, 300);
  const [predictions, setPredictions] = useState([]);
  const [isLocating, setIsLocating] = useState(false);
  const [locationError, setLocationError] = useState("");
  const [recentSearches, setRecentSearches] = useState<any[]>([]);
  
  const placesLib = useMapsLibrary("places");
  const geocodingLib = useMapsLibrary("geocoding");
  
  const autocompleteService = useRef(null);
  const placesService = useRef(null);
  const geocoder = useRef(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem("iyontree_recent_searches");
    if (saved) {
      try {
        setRecentSearches(JSON.parse(saved));
      } catch (error) {
        // Silently ignore parsing errors
      }
    }
  }, []);

  const saveRecentSearch = (name: string, lat: number, lng: number) => {
    setRecentSearches(prev => {
      const newItem = { name, lat, lng };
      const filtered = prev.filter(p => p.name !== name);
      const updated = [newItem, ...filtered].slice(0, 5);
      localStorage.setItem("iyontree_recent_searches", JSON.stringify(updated));
      return updated;
    });
  };

  const clearRecentSearches = () => {
    setRecentSearches([]);
    localStorage.removeItem("iyontree_recent_searches");
  };

  useEffect(() => {
    if (!placesLib || !geocodingLib) return;
    
    if (!autocompleteService.current) {
      autocompleteService.current = new placesLib.AutocompleteService();
    }
    if (!geocoder.current) {
      geocoder.current = new geocodingLib.Geocoder();
    }
    if (!placesService.current) {
      const dummyDiv = document.createElement('div');
      placesService.current = new placesLib.PlacesService(dummyDiv);
    }
  }, [placesLib, geocodingLib]);

  useEffect(() => {
    if (isOpen) {
      setSearchValue(item?.value || "");
      setPredictions([]);
      setTimeout(() => {
        inputRef.current?.focus();
      }, 50);
    }
  }, [isOpen, item]);

  useEffect(() => {
    if (debouncedSearchValue.length > 2 && autocompleteService.current) {
      autocompleteService.current.getPlacePredictions({ 
        input: debouncedSearchValue, 
        componentRestrictions: { country: "TR" } 
      }, (res, status) => {
        if (status === window.google.maps.places.PlacesServiceStatus.OK && res) {
          setPredictions(res);
        } else {
          setPredictions([]);
        }
      });
    } else {
      setPredictions([]);
    }
  }, [debouncedSearchValue]);

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchValue(e.target.value);
  };

  const handleSelectPrediction = (placeId: string) => {
    if (!placesService.current) return;
    placesService.current.getDetails({ 
      placeId, 
      fields: ['geometry', 'formatted_address'] 
    }, (place, status) => {
       if (status === window.google.maps.places.PlacesServiceStatus.OK && place && place.geometry) {
          const lat = place.geometry.location.lat();
          const lng = place.geometry.location.lng();
          const address = place.formatted_address;
          onSelectLocation(item.id, address, { lat, lng });
          saveRecentSearch(address, lat, lng);
          setSearchValue("");
          onClose();
       }
    });
  };

  const handleLocateClick = async () => {
    setLocationError("");
    if (!navigator.geolocation) {
      setLocationError(t.searchModal.locationNotSupported);
      return;
    }

    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        if (geocoder.current) {
          geocoder.current.geocode({ location: { lat: latitude, lng: longitude } }, (results, status) => {
            setIsLocating(false);
            if (status === 'OK' && results[0]) {
               const address = results[0].formatted_address;
               onSelectLocation(item.id, address, { lat: latitude, lng: longitude });
               saveRecentSearch(address, latitude, longitude);
               setSearchValue("");
               onClose();
            } else {
               setLocationError(t.searchModal.addressNotFound);
            }
          });
        } else {
          setIsLocating(false);
        }
      },
      (error) => {
        setIsLocating(false);
        if (error.code === error.PERMISSION_DENIED) {
          setLocationError(t.searchModal.permissionDenied);
        } else {
          setLocationError(t.searchModal.locateFailed);
        }
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  let title = t.searchModal.title;
  let placeholder = t.searchModal.placeholder;

  if (item?.currentIndex === 0) {
    title = t.searchModal.startTitle;
    placeholder = t.searchModal.startPlaceholder;
  } else if (item?.totalCount && item?.currentIndex === (item?.totalCount - 1)) {
    title = t.searchModal.destTitle;
    placeholder = t.searchModal.destPlaceholder;
  } else if (item?.totalCount > 3 && item?.currentIndex > 0) {
    title = item.currentIndex + ". " + t.searchModal.waypointTitle;
    placeholder = item.currentIndex + ". " + t.searchModal.waypointPlaceholder;
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent showCloseButton={false} className="sm:max-w-[500px] p-0 overflow-hidden bg-black/40 backdrop-blur-xl border border-white/20 shadow-2xl rounded-3xl z-[100] top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
        <div className="p-7 flex flex-col gap-6">
          <h3 className="text-xl font-bold text-white/90">{title}</h3>
          
          <div className="flex flex-col gap-2">
            <div className="relative group flex items-center">
              <Search size={22} className="absolute left-4 text-white/30 group-focus-within:text-blue-400 transition-colors" />
              <input 
                ref={inputRef}
                autoFocus
                type="text" 
                value={searchValue}
                onChange={handleSearch}
                placeholder={placeholder}
                className="w-full bg-white/5 border border-white/10 rounded-2xl py-4.5 pl-12 pr-24 text-white placeholder-white/20 focus:outline-none focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500/40 transition-all font-medium text-lg shadow-2xl" 
              />
              <div className="absolute right-4 flex items-center">
                {searchValue && (
                  <>
                    <button
                      type="button"
                      onClick={() => {
                        setSearchValue("");
                        setPredictions([]);
                        setTimeout(() => inputRef.current?.focus(), 0);
                      }}
                      className="p-1.5 text-white/50 hover:text-white transition-colors"
                      title={t.searchModal.clear}
                    >
                      <X size={18} />
                    </button>
                    <div className="w-px h-4 bg-white/20 mx-1" />
                  </>
                )}
                <button
                  type="button"
                  onClick={handleLocateClick}
                  disabled={isLocating}
                  className="p-1.5 text-white/50 hover:text-white transition-colors disabled:opacity-50"
                  title={t.searchModal.useCurrentLocation}
                >
                  {isLocating ? <Loader2 size={20} className="animate-spin" /> : <Target size={22} />}
                </button>
              </div>
            </div>
            {locationError && (
              <span className="text-red-400 text-sm pl-2">{locationError}</span>
            )}
          </div>

          <div className="flex flex-col min-h-[240px]">
             {predictions.length > 0 ? (
              <div className="flex flex-col gap-1">
                 <h4 className="text-white/20 text-xs font-bold uppercase tracking-widest mb-3 px-2">{t.searchModal.searchResults}</h4>
                 {predictions.map(pred => (
                   <button 
                     key={pred.place_id} 
                     onClick={() => handleSelectPrediction(pred.place_id)}
                     className="w-full max-w-full overflow-hidden flex items-center gap-4 p-4 rounded-2xl hover:bg-white/5 text-left transition-all group"
                    >
                     <div className="w-11 h-11 rounded-xl bg-white/5 flex items-center justify-center group-hover:bg-white/10 transition-colors shrink-0">
                       <MapPin size={22} className="text-white/30 group-hover:text-blue-400 transition-colors" />
                     </div>
                     <div className="flex flex-col min-w-0 flex-1 overflow-hidden">
                       <span className="block truncate w-full text-white/90 font-semibold text-[15px]">{pred.structured_formatting?.main_text || pred.description}</span>
                       <span className="block truncate w-full text-white/40 text-[13px] font-normal">{pred.structured_formatting?.secondary_text || 'Türkiye'}</span>
                     </div>
                   </button>
                 ))}
              </div>
            ) : (
              <div className="animate-in fade-in duration-500">
                 <div className="flex items-center justify-between mb-4 px-2">
                   <h4 className="text-white/20 text-xs font-bold uppercase tracking-widest">{t.searchModal.recentSearches}</h4>
                   {recentSearches.length > 0 && (
                     <button onClick={clearRecentSearches} className="text-white/40 hover:text-white text-xs transition-colors">{t.searchModal.clear}</button>
                   )}
                 </div>
                 
                 <div className="flex flex-col gap-1">
                   {recentSearches.length > 0 ? recentSearches.map((search, idx) => (
                     <button 
                       key={idx}
                       onClick={() => {
                         onSelectLocation(item.id, search.name, { lat: search.lat, lng: search.lng });
                         saveRecentSearch(search.name, search.lat, search.lng);
                         setSearchValue("");
                         onClose();
                       }}
                       className="w-full max-w-full overflow-hidden flex items-center gap-4 p-4 rounded-2xl hover:bg-white/5 text-left transition-all group"
                     >
                       <div className="w-11 h-11 rounded-xl bg-white/5 flex items-center justify-center group-hover:bg-white/10 transition-colors shrink-0">
                         <Clock size={20} className="text-white/20 group-hover:text-blue-400 transition-colors" />
                       </div>
                       <div className="flex flex-col min-w-0 flex-1 overflow-hidden">
                         <span className="block truncate w-full text-white/70 font-medium text-[15px]">{search.name}</span>
                       </div>
                     </button>
                   )) : (
                      <div className="px-2 py-4 text-white/30 text-sm">{t.searchModal.noRecentSearches}</div>
                   )}
                 </div>
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { Minus, Plus, LocateFixed, Layers, Car } from "lucide-react";
import { useMap } from "@vis.gl/react-google-maps";
import { cn } from "@/lib/utils";
import { translations } from "../lib/translations";
import { memo } from "react";

import { useSettings } from "../contexts/SettingsContext";

const MapControls = memo(({ 
  onLocateUser, 
}: { 
  onLocateUser: (loc: {lat: number, lng: number}) => void,
}) => {
  const { 
    language, 
    mapStyleKey: currentStyle, 
    setMapStyleKey: onStyleChange,
    showTraffic,
    setShowTraffic
  } = useSettings();
  const map = useMap();
  const t = translations[language];

  const onToggleTraffic = () => setShowTraffic(!showTraffic);

  const handleZoomIn = () => {
    if (map) map.setZoom((map.getZoom() || 0) + 1);
  };

  const handleZoomOut = () => {
    if (map) map.setZoom((map.getZoom() || 0) - 1);
  };

  const handleLocateMe = () => {
    if (!map) return;

    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const pos = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
          };
          map.panTo(pos);
          map.setZoom(15);
          onLocateUser(pos);
        },
        () => {
          console.error("Geolocation service failed.");
        }
      );
    }
  };

  const handleToggleLayers = () => {
    const styles: ('default' | 'light' | 'dark' | 'satellite')[] = ['default', 'light', 'dark', 'satellite'];
    const currentIndex = styles.indexOf(currentStyle as any);
    const nextIndex = currentIndex === -1 ? 0 : (currentIndex + 1) % styles.length;
    const nextStyle = styles[nextIndex];
    onStyleChange(nextStyle);

    if (map) {
      map.setMapTypeId(nextStyle === 'satellite' ? 'hybrid' : 'roadmap');
    }
  };

  return (
    <div className="absolute bottom-6 right-6 z-40 pointer-events-auto">
      <div className="flex flex-row items-center h-10 px-1 bg-black/40 backdrop-blur-xl border border-white/20 rounded-xl shadow-2xl gap-0.5">
        <button 
          onClick={handleZoomOut}
          className="w-8 h-8 text-white/80 hover:text-white hover:bg-white/10 rounded-lg transition-all cursor-pointer flex items-center justify-center"
          title={t.zoomOut}
        >
          <Minus size={18} />
        </button>

        <div className="w-px h-4 bg-white/20 mx-0.5" />

        <button 
          onClick={handleZoomIn}
          className="w-8 h-8 text-white/80 hover:text-white hover:bg-white/10 rounded-lg transition-all cursor-pointer flex items-center justify-center"
          title={t.zoomIn}
        >
          <Plus size={18} />
        </button>

        <div className="w-px h-4 bg-white/20 mx-0.5" />

        <button 
          onClick={handleLocateMe}
          className="w-8 h-8 text-white/80 hover:text-white hover:bg-white/10 rounded-lg transition-all cursor-pointer flex items-center justify-center"
          title={t.locateMe}
        >
          <LocateFixed size={18} />
        </button>

        <div className="w-px h-4 bg-white/20 mx-0.5" />

        <button 
          onClick={onToggleTraffic}
          className={cn(
            "h-8 px-2 rounded-lg transition-all cursor-pointer flex items-center justify-center min-w-[38px]",
            showTraffic ? "text-cyan-400 bg-cyan-400/10" : "text-white/80 hover:text-white hover:bg-white/10"
          )}
          title={t.showTraffic}
        >
          <Car size={18} />
        </button>

        <div className="w-px h-4 bg-white/20 mx-0.5" />

        <button 
          onClick={handleToggleLayers}
          className={cn(
            "h-8 px-2 rounded-lg transition-all cursor-pointer flex flex-col items-center justify-center gap-0 min-w-[44px]",
            currentStyle !== 'default' ? "text-cyan-400 bg-cyan-400/10" : "text-white/80 hover:text-white hover:bg-white/10"
          )}
          title={t.changeMapStyle}
        >
          <Layers size={18} />
          <span className="text-[8px] font-bold uppercase tracking-tighter leading-none">{currentStyle === 'system' ? 'AUTO' : currentStyle}</span>
        </button>
      </div>
    </div>
  );
});

export default MapControls;

import { Dialog, DialogContent, DialogHeader, DialogTitle } from "./ui/dialog";
import { Search, Edit2, Trash2, Plus, CarFront, Check } from "lucide-react";
import { Button } from "./ui/button";
import { useVehicle } from "../contexts/VehicleContext";
import { useSettings } from "../contexts/SettingsContext";
import { translations } from "../lib/translations";
import type { Vehicle } from "../types/vehicle";
import { useState } from "react";
import { cn } from "@/lib/utils";

export default function MyGarageModal({ 
  isOpen, 
  onClose, 
  onOpenAddVehicle 
}: { 
  isOpen: boolean, 
  onClose: () => void, 
  onOpenAddVehicle: () => void 
}) {
  const { language } = useSettings();
  const t = translations[language];
  const { vehicles, setVehicles, selectedVehicleId, setSelectedVehicleId } = useVehicle();
  const [searchTerm, setSearchTerm] = useState("");

  const filteredVehicles = vehicles.filter(v => 
    v.brand.toLowerCase().includes(searchTerm.toLowerCase()) || 
    v.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    v.customName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectVehicle = (id: string) => {
    setSelectedVehicleId(id);
    onClose();
  };

  const handleDeleteVehicle = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setVehicles(prev => prev.filter(v => v.id !== id));
    if (selectedVehicleId === id) {
      setSelectedVehicleId(null);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[480px] glass-panel border-white/20 p-0 overflow-hidden bg-black/60 shadow-2xl">
        <DialogHeader className="p-6 pb-4 border-b border-white/10">
          <DialogTitle className="text-xl font-semibold text-white tracking-tight flex items-center gap-2">
            {t.myGarage} ({vehicles.length}/5)
          </DialogTitle>
        </DialogHeader>

        <div className="p-6 flex flex-col gap-6 bg-zinc-950/40 min-h-[400px]">

          <div className="flex flex-col gap-3 overflow-y-auto max-h-[300px] custom-scrollbar pr-1">
             {filteredVehicles.map(v => (
               <div 
                 key={v.id} 
                 className={cn(
                   "group relative bg-white/5 hover:bg-white/10 transition-all border rounded-2xl p-4 flex items-center justify-between cursor-pointer active:scale-[0.98]",
                   selectedVehicleId === v.id ? "border-cyan-500/50 bg-cyan-500/5" : "border-white/10"
                 )} 
                 onClick={() => handleSelectVehicle(v.id)}
               >
                 <div className="flex items-center gap-4">
                    <div className={cn(
                        "w-10 h-10 rounded-full flex items-center justify-center transition-colors",
                        selectedVehicleId === v.id ? "bg-cyan-500 text-black" : "bg-white/10 text-white/80"
                      )}>
                      {selectedVehicleId === v.id ? <Check size={20} /> : <CarFront size={20} />}
                    </div>
                    <div>
                      <h4 className="text-white font-medium text-[15px]">{v.customName}</h4>
                      <p className="text-white/50 text-xs mt-0.5">
                        {v.brand} {v.model} {v.soc !== undefined && `· %${v.soc}`}
                      </p>
                    </div>
                 </div>

                 <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
