import { createContext, useContext, useState, type ReactNode } from 'react';

interface AuthContextType {
  currentUser: any;
  setCurrentUser: (user: any) => void;
  isAuthModalOpen: boolean;
  setIsAuthModalOpen: (open: boolean) => void;
  authMessage: string;
  setAuthMessage: (msg: string) => void;
  requireAuth: (message?: string) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authMessage, setAuthMessage] = useState('');

  const requireAuth = (message?: string) => {
    setAuthMessage(message || '');
    setIsAuthModalOpen(true);
  };

  return (
    <AuthContext.Provider value={{
      currentUser, setCurrentUser,
      isAuthModalOpen, setIsAuthModalOpen,
      authMessage, setAuthMessage,
      requireAuth
    }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import { createContext, useContext, useState, useEffect, type ReactNode } from 'react';
import { lightMapStyle, darkMapStyle } from "../lib/mapStyles";

interface SettingsContextType {
  language: 'tr' | 'en';
  setLanguage: (lang: 'tr' | 'en') => void;
  mapStyleKey: 'default' | 'light' | 'dark' | 'satellite' | 'system';
  setMapStyleKey: (key: 'default' | 'light' | 'dark' | 'satellite' | 'system') => void;
  getMapStyle: () => any[];
  showTraffic: boolean;
  setShowTraffic: (show: boolean) => void;
  showCookieBanner: boolean;
  setShowCookieBanner: (show: boolean) => void;
  showCookieModal: boolean;
  setShowCookieModal: (show: boolean) => void;
  handleSaveCookies: (prefs: any) => void;
}

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

export function SettingsProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<'tr' | 'en'>(() => {
    const saved = localStorage.getItem('iyontree_language');
    return (saved === 'en' || saved === 'tr') ? saved : 'tr';
  });

  const [mapStyleKey, setMapStyleKey] = useState<'default' | 'light' | 'dark' | 'satellite' | 'system'>(() => {
    const saved = localStorage.getItem('iyontree_map_style');
    const valid = ['default', 'light', 'dark', 'satellite', 'system'];
    return (saved && valid.includes(saved)) ? (saved as any) : 'system';
  });

  const [showTraffic, setShowTraffic] = useState(false);
  const [showCookieBanner, setShowCookieBanner] = useState(() => {
    if (typeof window === 'undefined') return false;
    const saved = localStorage.getItem('iyontree_cookies');
    if (!saved) return true;
    try {
      const parsed = JSON.parse(saved);
      const is30DaysOld = (Date.now() - parsed.timestamp) > 30 * 24 * 60 * 60 * 1000;
      return !parsed.allAccepted && is30DaysOld;
    } catch (error) {
      return true;
    }
  });
  const [showCookieModal, setShowCookieModal] = useState(false);

  useEffect(() => {
    localStorage.setItem('iyontree_language', language);
    document.documentElement.lang = language;
    document.documentElement.className = "notranslate";
  }, [language]);

  useEffect(() => {
    localStorage.setItem('iyontree_map_style', mapStyleKey);
  }, [mapStyleKey]);

  const handleSaveCookies = (prefs: any) => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('iyontree_cookies', JSON.stringify(prefs));
    }
    setShowCookieBanner(false);
    setShowCookieModal(false);
  };

  const getMapStyle = () => {
    let effective: 'light' | 'dark' | 'default' | 'satellite' = 'light';

    if (mapStyleKey === 'system') {
      const isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      effective = isDark ? 'dark' : 'light';
    } else {
      effective = mapStyleKey as any;
    }

    if (effective === 'light') return lightMapStyle;
    if (effective === 'dark') return darkMapStyle;
    return [];
  };

  return (
    <SettingsContext.Provider value={{
      language, setLanguage,
      mapStyleKey, setMapStyleKey,
      getMapStyle,
      showTraffic, setShowTraffic,
      showCookieBanner, setShowCookieBanner,
      showCookieModal, setShowCookieModal,
      handleSaveCookies
    }}>
      {children}
    </SettingsContext.Provider>
  );
}

export function useSettings() {
  const context = useContext(SettingsContext);
  if (context === undefined) {
    throw new Error('useSettings must be used within a SettingsProvider');
  }
  return context;
}

import { createContext, useContext, useState, useEffect, type ReactNode } from 'react';
import type { Vehicle } from '../types/vehicle';

interface VehicleContextType {
  vehicles: Vehicle[];
  setVehicles: React.Dispatch<React.SetStateAction<Vehicle[]>>;
  selectedVehicleId: string | null;
  setSelectedVehicleId: (id: string | null) => void;
  selectedVehicle: Vehicle | null;
}

const VehicleContext = createContext<VehicleContextType | undefined>(undefined);

export function VehicleProvider({ children }: { children: ReactNode }) {
  // Try to load initial state from localStorage
  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    try {
      const saved = localStorage.getItem('iyontree_vehicles');
      return saved ? JSON.parse(saved) : [];
    } catch (error) {
      console.error('Failed to load vehicles from localStorage', error);
      return [];
    }
  });

  const [selectedVehicleId, setSelectedVehicleId] = useState<string | null>(() => {
    return localStorage.getItem('iyontree_selected_vehicle_id');
  });

  // Save vehicles to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('iyontree_vehicles', JSON.stringify(vehicles));
  }, [vehicles]);

  // Save selectedVehicleId to localStorage whenever it changes
  useEffect(() => {
    if (selectedVehicleId) {
      localStorage.setItem('iyontree_selected_vehicle_id', selectedVehicleId);
    } else {
      localStorage.removeItem('iyontree_selected_vehicle_id');
    }
  }, [selectedVehicleId]);

  const selectedVehicle = vehicles.find(v => v.id === selectedVehicleId) || null;

  return (
    <VehicleContext.Provider value={{
      vehicles, setVehicles,
      selectedVehicleId, setSelectedVehicleId,
      selectedVehicle
    }}>
      {children}
    </VehicleContext.Provider>
  );
}

export function useVehicle() {
  const context = useContext(VehicleContext);
  if (context === undefined) {
    throw new Error('useVehicle must be used within a VehicleProvider');
  }
  return context;
}

import { useState, useEffect } from "react";
import { translations } from "../lib/translations";

const MOCK_USER = {
  email: 'admin@iyontree.com',
  password: '1234',
  firstName: 'admin',
  lastName: 'admin',
  phone: '(111) 111-11-11'
};

import { useSettings } from "../contexts/SettingsContext";
import { loginSchema, registerSchema } from "../lib/validation";
import { z } from "zod";

export type AuthStep = 'email' | 'password' | 'register' | 'verify_email' | 'reset_password';

export function useAuthForm(onLogin?: (user: any) => void, onClose?: () => void) {
  const { language } = useSettings();
  const [authStep, setAuthStep] = useState<AuthStep>('email');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [phone, setPhone] = useState('');
  const [authError, setAuthError] = useState('');
  const [otp, setOtp] = useState('');
  const [timeLeft, setTimeLeft] = useState(120);
  const [otpError, setOtpError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<{ [key: string]: string }>({});

  useEffect(() => {
    if (authStep !== 'verify_email' || timeLeft <= 0) return;

    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [authStep, timeLeft]);

  const resetForm = () => {
    setAuthStep('email');
    setEmail('');
    setPassword('');
    setConfirmPassword('');
    setFirstName('');
    setLastName('');
    setPhone('');
    setOtp('');
    setTimeLeft(120);
    setOtpError('');
    setAuthError('');
  };

  const handleEmailSubmit = () => {
    setAuthError('');
    setFieldErrors({});
    if (!email) return;

    try {
      z.object({ email: z.string().email() }).parse({ email });
      if (email.toLowerCase() === MOCK_USER.email) {
        setAuthStep('password');
      } else {
        setAuthStep('register');
      }
    } catch (err) {
      setAuthError(language === 'tr' ? 'Lütfen geçerli bir e-posta girin.' : 'Please enter a valid email.');
    }
  };

  const handlePasswordSubmit = () => {
    setAuthError('');
    setFieldErrors({});

    const result = loginSchema.safeParse({ email, password });
    if (!result.success) {
      setAuthError(result.error.issues[0].message);
      return;
    }

    if (password === MOCK_USER.password) {
      if (onLogin) onLogin(MOCK_USER);
      if (onClose) onClose();
    } else {
      setAuthError(language === 'tr' ? "Girdiğiniz şifre hatalı." : "Incorrect password.");
    }
  };

  const handleRegisterSubmit = () => {
    setFieldErrors({});
    setAuthError('');

    const result = registerSchema.safeParse({
      email, firstName, lastName, phone, password, confirmPassword
    });

    if (!result.success) {
      const newErrors: { [key: string]: string } = {};
      result.error.issues.forEach(issue => {
        if (issue.path[0]) newErrors[issue.path[0] as string] = issue.message;
      });
      setFieldErrors(newErrors);
      return;
    }

    if (onLogin) onLogin({ email, firstName, lastName, phone });
    handleCloseToModal();
  };

  const handleCloseToModal = () => {
    if (onClose) onClose();
    resetForm();
  };

  const handleOtpChange = (val: string) => {
    const cleanVal = val.replace(/[^0-9]/g, '');
    if (cleanVal.length <= 6) {
      setOtp(cleanVal);
      setOtpError('');

      if (cleanVal.length === 6) {
        if (cleanVal === '111111') {
          setOtpError('');
          setAuthStep('reset_password');
        } else {
          setOtpError(language === 'tr' ? 'Hatalı doğrulama kodu.' : 'Invalid verification code.');
        }
      }
    }
  };

  const handleResend = () => {
    setTimeLeft(120);
    setOtp('');
    setOtpError('');
  };

  const handleGoToVerify = () => {
    setAuthStep('verify_email');
    setTimeLeft(120);
    setOtp('');
    setOtpError('');
    setAuthError('');
  };

  const isPasswordsMatch = password === confirmPassword;

  return {
    authStep,
    setAuthStep,
    email,
    setEmail,
    password,
    setPassword,
    confirmPassword,
    setConfirmPassword,
    firstName,
    setFirstName,
    lastName,
    setLastName,
    phone,
    setPhone,
    authError,
    setAuthError,
    otp,
    setOtp,
    timeLeft,
    otpError,
    resetForm,
    handleEmailSubmit,
    handlePasswordSubmit,
    handleOtpChange,
    handleResend,
    handleGoToVerify,
    isPasswordsMatch,
    fieldErrors,
    handleRegisterSubmit
  };
}

