        </header>

        {/* Main Content Area */}
        <main className={`flex-1 w-full max-w-7xl mx-auto px-6 ${isHome ? 'py-20' : 'py-16'} relative z-10 flex flex-col gap-12`}>
          {/* Title Section for Subpages */}
          {(title || subtitle) && (
